style.css:
@-moz-document domain("youtube.com") {
/* Set the background image */
  body {
    background: url('https://c4.wallpaperflare.com/wallpaper/740/654/427/1920x1080-px-beautiful-christmas-gift-holiday-merry-santa-snow-tree-winter-animals-bears-hd-art-wallpaper-preview.jpg') no-repeat center center fixed;
    background-size: cover;
  }

  /* Adjust the YouTube dark overlay so buttons are still visible */
  ytd-app {
    background-color: rgba(0, 0, 0, 0.5); /* semi-transparent overlay */
  }

  /* Optional: Change color of text to improve contrast */
  ytd-video-primary-info-renderer, ytd-search-pyv-renderer, ytd-thumbnail {
    color: white !important;
  }

  /* Optional: Fixing buttons visibility */
  ytd-button-renderer, ytd-toggle-button-renderer {
    background-color: rgba(0, 0, 0, 0.3) !important; /* semi-transparent button background */
    color: white !important; /* change button text color */
  }

  /* Ensure the sidebar and other elements are not obscured */
  #content {
    z-index: 2;
    position: relative;
  }
}
